defmodule Exmaster.QR2Test do
  use ExUnit.Case, async: true

  alias Exmaster.QR2

  # A Battlefield Vietnam 1.21 server's first heartbeat, captured on
  # loopback: 49 keys, then empty player and team sections.
  @heartbeat Base.decode16!(
               ""
             )

  test "a heartbeat's keys, empty values and all" do
    assert {:heartbeat, <<0xD3, 0xB7, 0x54, 0xD5>>, payload} = QR2.parse(@heartbeat)
    assert {:ok, keys} = QR2.parse_keys(payload)
    assert length(keys) == 49
    assert hd(keys) == {"localip0", "192.168.1.26"}
    assert {"statechanged", "3"} in keys
    assert {"gamename", "bfvietnam"} in keys
    assert {"bot_skill", ""} in keys
    assert {"gamever", "v1.21"} in keys

    # Keys that don't end aren't a heartbeat.
    assert QR2.parse_keys("hostname\0x\0gamename\0bfvietnam") == :error
    assert QR2.parse_keys("hostname") == :error
    assert QR2.parse_keys(<<0>>) == {:ok, []}
  end

  test "the other packets" do
    assert QR2.parse(<<9, 0::32, "bfvietnam", 0>>) == {:available, "bfvietnam"}
    assert QR2.parse(<<1, 1, 2, 3, 4, "abc", 0>>) == {:response, <<1, 2, 3, 4>>, "abc"}
    assert QR2.parse(<<8, 1, 2, 3, 4>>) == :other
    assert QR2.parse(<<3, 1, 2>>) == :other
    assert QR2.parse("") == :other

    assert QR2.challenge_packet(<<1, 2, 3, 4>>, "abc") == <<0xFE, 0xFD, 1, 1, 2, 3, 4, "abc", 0>>
    assert QR2.registered_packet(<<1, 2, 3, 4>>) == <<0xFE, 0xFD, 0x0A, 1, 2, 3, 4>>
    assert QR2.available_packet() == <<0xFE, 0xFD, 9, 0, 0, 0, 0>>
  end

  test "games and their keys" do
    assert QR2.key("bfvietnam") == "h2P9dJ"
    assert QR2.default_port("bfvietnam") == 23_000
    assert QR2.client_key("gslive") == "Xn221z"
    assert {QR2.key("ut3pc"), QR2.default_port("ut3pc")} == {"nT2Mtz", 6_500}
    # A UT3 server's response to exmaster's challenge, captured.
    assert Exmaster.GS.validate("jMijzR007F0000011964", "nT2Mtz") ==
             "MzGpm6F0mqyVLT1hC5MpDmt4RvEA"

    assert QR2.key("gslive") == nil
    assert QR2.client_key("nosuchgame") == nil
  end
end
